func (q *Queries) SetMfaLastStep(ctx context.Context, arg SetMfaLastStepParams) (int64, error) {
	result, err := q.db.Exec(ctx, setMfaLastStep, arg.Step, arg.UserID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

